def balanced(s):
    """Return True if all brackets in *s* are properly balanced.

    Double-quoted strings are ignored. Inside a string, a backslash escapes
    the next character, so an escaped quote does not terminate the string.
    An unterminated string makes the result False.
    """
    stack = []
    in_string = False
    matching = {')': '(', ']': '[', '}': '{'}

    i = 0
    while i < len(s):
        ch = s[i]

        if in_string:
            if ch == '\\':
                # Skip the escaped character. If it is the final character,
                # the string remains unterminated and we return False below.
                i += 2
                continue
            if ch == '"':
                in_string = False
            i += 1
            continue

        if ch == '"':
            in_string = True
        elif ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()

        i += 1

    return not in_string and not stack
